		&o.ToolsNetem.Delay,
		"delay",
		"",
		o.ToolsNetem.Delay,
		"time to delay outgoing packets (e.g. 100ms, 2s)",
	)
	netemSetCmd.Flags().DurationVarP(
		&o.ToolsNetem.Jitter,
		"jitter",
		"",
		o.ToolsNetem.Jitter,
		"delay variation, aka jitter (e.g. 50ms)",
	)
