	)
	netemSetCmd.Flags().Uint64VarP(
		&o.ToolsNetem.Rate,
		"rate",
		"",
		o.ToolsNetem.Rate, "link rate limit in kbit")
	netemSetCmd.Flags().Float64VarP(
		&o.ToolsNetem.Corruption,
		"corruption",
