+
+func netemLab(o *Options) (*clabcore.CLab, error) {
+	if o.Global.TopologyFile == "" && o.Global.TopologyName == "" {
+		return nil, fmt.Errorf("--topo/-t or --name is required with lab runtime %q",
+			o.Global.Runtime)
+	}
