+	if err == nil ||
+		!strings.Contains(err.Error(), `interface "eth9" of node "r2" is not on a link`) {
+		t.Fatalf("SetImpairment() error = %v", err)
+	}
+}
+
+func TestSetImpairmentRejectsATopologyOwnedLab(t *testing.T) {
